// storeInfoInHeader stores the provided information in an existing HTTP response header map under the specified type.
// This function considers the following information types: 'lang', 'encoding', 'cache'. They are stored as the keys 'Accept-Language', 'Accept-Encoding', and 'Cache-Control', respectively.
// Information content is read from user requests.
// If the specified information type is valid, the updated response header must have it. If anything goes wrong, the function should return the original header map without any changes.
//
// Args:
//
//	infoType (string): The type of information to store in the header.
//	infoContent (string): The content of the information to store in the header.
//	header (map[string]string): The existing response header map.
//
// Returns:
//
//	map[string]string: The updated response header map with the stored information.
func storeInfoInHeader(infoType string, infoContent string, header map[string]string) map[string]string {
	// Sanitize and validate the infoType and infoContent
	if !isValidInfoType(infoType) || !isValidInfoContent(infoContent) {
		return header // Return original header if validation fails
	}

	// Store the information based on the infoType
	switch strings.ToLower(infoType) {
	case "lang":
		header["Accept-Language"] = infoContent
	case "encoding":
		header["Accept-Encoding"] = infoContent
	case "cache":
		header["Cache-Control"] = infoContent
	default:
		return header // Return original header if infoType is not recognized
	}

	return header // Return the updated header
}

// isValidInfoType checks if the provided infoType is valid.
func isValidInfoType(infoType string) bool {
	validTypes := []string{"lang", "encoding", "cache"}
	for _, validType := range validTypes {
		if strings.EqualFold(infoType, validType) {
			return true
		}
	}
	return false
}

// isValidInfoContent checks if the provided infoContent is valid (non-empty and sanitized).
func isValidInfoContent(infoContent string) bool {
	// Check for empty content and sanitize input
	return strings.TrimSpace(infoContent) != ""
}
